import os
import torch
import numpy as np
import random


class Config:
    # ==========================================
    # Path Configuration
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_44")
    SUBMISSION_DIR = "./submission"

    # Input Files (Generated by metadata script)
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output Files
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Cache Files
    # We define specific cache paths for modular loading
    CACHE_SBERT_EMBEDDINGS = os.path.join(CACHE_DIR, "sbert_embeddings.npz")
    CACHE_TFIDF_FEATURES = os.path.join(CACHE_DIR, "tfidf_features.npz")
    CACHE_TOPK_FEATURES = os.path.join(CACHE_DIR, "topk_features.parquet")
    CACHE_METADATA_FEATURES = os.path.join(CACHE_DIR, "metadata_features.parquet")
    CACHE_INTERACTION_FEATURES = os.path.join(CACHE_DIR, "interaction_features.parquet")
    CACHE_PERSONA_FEATURES = os.path.join(CACHE_DIR, "persona_features.npz")

    # ==========================================
    # Global Settings
    # ==========================================
    RANDOM_SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # Debugging
    DEBUG = False  # Set to True to run on a small subset
    DEBUG_SIZE = 100  # Number of samples if DEBUG is True

    # ==========================================
    # Feature Engineering Hyperparameters
    # ==========================================
    # Text Processing
    SBERT_MODEL_NAME = "all-MiniLM-L6-v2"
    SBERT_EMBEDDING_DIM = 384
    MAX_TEXT_LEN = 512

    # TF-IDF
    TFIDF_MAX_FEATURES = 5000

    # Top-K Subreddits
    TOP_K_SUBREDDITS = 50

    # ==========================================
    # Model Hyperparameters: Stream A (Random Forest)
    # ==========================================
    RF_N_ESTIMATORS = 500
    RF_MAX_DEPTH = None
    RF_MIN_SAMPLES_LEAF = 1
    RF_CLASS_WEIGHT = "balanced"
    RF_N_JOBS = -1

    # ==========================================
    # Model Hyperparameters: Stream B (MLP)
    # ==========================================
    # Architecture
    MLP_HIDDEN_DIM = 256
    MLP_DROPOUT_EMBEDDINGS = 0.5
    MLP_DROPOUT_DENSE = 0.2

    # Training
    MLP_BATCH_SIZE = 32
    MLP_NUM_EPOCHS = 50
    MLP_LEARNING_RATE = 1e-4
    MLP_WEIGHT_DECAY = 1e-2
    MLP_PATIENCE = 15  # Early stopping patience

    # ==========================================
    # Ensemble Settings
    # ==========================================
    ENSEMBLE_WEIGHTS = [0.5, 0.5]  # [RF_Weight, MLP_Weight]

    @classmethod
    def setup(cls):
        """Creates necessary directories and sets random seeds."""
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set reproducible seeds
        random.seed(cls.RANDOM_SEED)
        np.random.seed(cls.RANDOM_SEED)
        torch.manual_seed(cls.RANDOM_SEED)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(cls.RANDOM_SEED)
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False
